package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for LocaleUtils.countriesByLanguage
 */
public class LocaleUtils_countriesByLanguage_TriageGen1Test {

    @Test
    public void testCountriesByLanguage_WithNullLanguageCode() {
        // Tests the branch: if (countries == null) -> if (languageCode != null) -> else { countries = Collections.EMPTY_LIST; }
        List result = LocaleUtils.countriesByLanguage(null);
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_WithValidLanguageCode() {
        // Tests the branch: if (countries == null) -> if (languageCode != null) -> loop through locales
        // We use "en" as a common language code to ensure we hit the logic
        String lang = "en";
        List result = LocaleUtils.countriesByLanguage(lang);

        assertNotNull(result);
        // Check if the returned locales actually match the language code
        for (Object obj : result) {
            Locale locale = (Locale) obj;
            assertEquals(lang, locale.getLanguage());
        }
    }

    @Test
    public void testCountriesByLanguage_WithNonExistentLanguageCode() {
        // Tests the branch: languageCode is not null, but no locales match the criteria
        // Using a highly unlikely language code to ensure empty list
        String lang = "zzzz"; 
        List result = LocaleUtils.countriesByLanguage(lang);

        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_CachingEffect() {
        // Tests the branch: if (countries == null) is false (Cache hit)
        String lang = "fr";

        // First call to populate cache
        List firstCall = LocaleUtils.countriesByLanguage(lang);

        // Second call should hit the cache
        List secondCall = LocaleUtils.countriesByLanguage(lang);

        assertNotNull(firstCall);
        assertNotNull(secondCall);
        assertSame("The returned list should be the same instance from the cache", firstCall, secondCall);
    }

    @Test
    public void testCountriesByLanguage_LocaleFilteringLogic() {
        // This test targets the specific logic inside the loop:
        // locale.getLanguage().equals(languageCode) && locale.getCountry().length() != 0 && locale.getVariant().length() == 0

        // Given that we cannot easily mock the static availableLocaleList() without PowerMock,
        // we rely on the fact that standard locales like "en_US" satisfy:
        // language="en", country="US" (length != 0), variant="" (length == 0)

        List enCountries = LocaleUtils.countriesByLanguage("en");

        for (Object obj : enCountries) {
            Locale locale = (Locale) obj;
            assertEquals("en", locale.getLanguage());
            assertNotEquals(0, locale.getCountry().length());
            assertEquals(0, locale.getVariant().length());
        }
    }
}
